  parsed = parseArgs({
    args: process.argv.slice(2),
    allowPositionals: true,
    options: {
      every: { type: 'string' },
      since: { type: 'string' },
      within: { type: 'string' },
      today: { type: 'string' },
      file: { type: 'string' },
      help: { type: 'boolean', short: 'h' },
